{{ feed_url | safe }}
{%- for page in pages %}

    {{ page.title }}
    {{ page.date | date(format="%F") }}
    {{ (page.updated or page.date) | date(format="%F") }}
    {% for author in page.authors %}


        {{ author }}


    {% else %}


        {%- if config.author -%}
          {{ config.author }}
        {%- else -%}
          Unknown
        {%- endif -%}


    {% endfor %}

    {{ page.permalink | safe }}
    {% if page.summary %}
      {% set feed_source = page.summary %}
    {% else %}
      {% set feed_source = page.content %}
    {% endif %}
    {% set_global feed_body = "" %}
    {% for chunk in feed_source | split(pat="") %}
      {% if loop.first %}
        {% set_global feed_body = feed_body ~ chunk %}
      {% else %}
        {% set web_parts = chunk | split(pat="") %}
        {% set after_slideshow = web_parts | nth(n=1) %}
        {% set_global feed_body = feed_body ~ after_slideshow %}
      {% endif %}
    {% endfor %}
    {% set feed_body = feed_body
      | replace(from="", to="")
    %}
    {% if page.summary %}
    {{ feed_body }}
    {% else %}
    {{ feed_body }}
    {% endif %}

{%- endfor %}
